<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {validateShift} from '../time'
import {copyAttendanceRules,defaultAttendanceRules,shiftDuration,shiftRuleSummary,useRestPolicyText,validAttendanceRules,type AttendanceRuleTemplates,type AttendanceRuleTemplate,type AttendanceRules} from '../restPolicy'
import type {Shift,ShiftWrite} from '../types'
import PhaseStatus from '../components/PhaseStatus.vue'
import AttendanceRulesEditor from '../components/AttendanceRulesEditor.vue'
import ShiftPresetPicker from '../components/ShiftPresetPicker.vue'
import {restaurantShiftRange,restaurantText} from '../restaurantShifts'
const route=useRoute(),router=useRouter(),existing=String(route.params.id||''),id=existing||crypto.randomUUID()
const {api,home,t,p,base,loading,busy,failure,load,write,english}=usePhasePage(),templatePage=usePhasePage(),{r}=useRestPolicyText()
const draft=ref<ShiftWrite>({expectedVersion:0,name:'',startTime:'09:00',endTime:'18:00',nextDay:false,startNextDay:false,breakMode:'none',breakMinutes:30,breakAfterMinutes:360,breakStartOffset:180,breakEndOffset:210,breakPaid:false,enabled:true,rules:null}),ready=ref(!existing),templates=ref<AttendanceRuleTemplate[]>([]),selected=ref(''),copied=ref(false),backup=ref<AttendanceRules|null>(null)
const rulesEnabled=computed({get:()=>!!draft.value.rules,set:(enabled:boolean)=>{if(enabled)draft.value.rules=backup.value||defaultAttendanceRules(english());else{backup.value=draft.value.rules||null;draft.value.rules=null}}}),duration=computed(()=>shiftDuration(draft.value.startTime,draft.value.endTime,draft.value.nextDay))
onMounted(()=>{if(!home.value?.employeeManage)return;if(existing)void load(()=>api().get<Shift[]>('/shifts'),items=>{const s=items.find(x=>x.id===id);if(!s){failure.value=t('notFound');return}draft.value={...s,rules:s.rules?copyAttendanceRules(s.rules):null,expectedVersion:s.version};ready.value=true});void templatePage.load(()=>api().get<AttendanceRuleTemplates>('/attendance-rule-templates'),data=>templates.value=data.items.filter(item=>item.enabled))})
function selectTemplate(){const template=templates.value.find(item=>item.id===selected.value);if(!template)return;draft.value.rules={...copyAttendanceRules(template.rules),sourceTemplateId:template.id,sourceTemplateVersion:template.version};copied.value=true}
function save(){const s=draft.value;if(!validateShift(s.rules?{...s,breakMode:'none'}:s)||(s.rules&&!validAttendanceRules(s.rules,duration.value))){failure.value=s.rules?r('invalid'):p('invalid');return}const body={expectedVersion:s.expectedVersion,name:s.name.trim(),startTime:s.startTime,endTime:s.endTime,nextDay:s.nextDay,...(s.startNextDay?{startNextDay:true}:{}),breakMode:s.breakMode,breakMinutes:s.breakMode==='duration'?s.breakMinutes:0,breakAfterMinutes:s.breakMode==='duration'?s.breakAfterMinutes:0,breakStartOffset:s.breakMode==='window'?s.breakStartOffset:0,breakEndOffset:s.breakMode==='window'?s.breakEndOffset:0,breakPaid:s.breakPaid,enabled:s.enabled,rules:s.rules||null};void write(()=>api().put('/shifts/'+id,body),()=>router.push(base.value+'/shifts').then(()=>{}))}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{p(existing?'editShift':'newShift')}}</h2><PhaseStatus :failure="failure" :loading="loading"/><p v-if="!home?.employeeManage" role="alert">{{t('noAccess')}}</p><form v-else-if="ready&&!loading" @submit.prevent="save"><fieldset :disabled="busy"><ShiftPresetPicker @apply="Object.assign(draft,$event)"/><label>{{p('name')}}<input v-model="draft.name" required maxlength="80"></label><div class="wf-grid"><label>{{p('startTime')}}<input v-model="draft.startTime" type="time" required></label><label>{{p('endTime')}}<input v-model="draft.endTime" type="time" required></label></div><label class="wf-check"><input v-model="draft.startNextDay" type="checkbox">{{english()?'Starts next day (still assigned to selected business date)':'次日开始（仍归所选营业日期）'}}</label><label class="wf-check"><input v-model="draft.nextDay" type="checkbox">{{english()?'Ends the day after the actual start date':'次日结束（相对实际开始日）'}}</label><p class="wf-hint" role="status">{{restaurantShiftRange(draft,english())}} · {{restaurantText(english()).midnight}}</p><label class="wf-check"><input v-model="rulesEnabled" type="checkbox">{{r('enableRules')}}</label><p class="wf-hint">{{r('legacy')}}</p><template v-if="draft.rules"><PhaseStatus :failure="templatePage.failure.value" :loading="templatePage.loading.value"/><label>{{r('template')}}<select v-model="selected" :disabled="templatePage.loading.value" @change="selectTemplate"><option value="">{{r('choose')}}</option><option v-for="item in templates" :key="item.id" :value="item.id">{{item.name}} · v{{item.version}}</option></select></label><p v-if="!templates.length&&!templatePage.loading.value&&!templatePage.failure.value" class="wf-hint">{{r('noTemplates')}}</p><p v-if="copied" class="wf-hint">{{r('copied')}}</p><p v-if="draft.rules.sourceTemplateId" class="wf-hint">{{r('snapshot')}}: {{draft.rules.sourceTemplateVersion}}</p><p class="wf-hint wf-rule-plan" role="status">{{shiftRuleSummary(draft,'',english(),duration)}}</p><AttendanceRulesEditor v-model="draft.rules" :start-time="draft.startTime" :duration="duration" :disabled="busy"/></template><template v-else><label>{{p('breakMode')}}<select v-model="draft.breakMode"><option v-for="mode in (['none','duration','window','manual'] as const)" :key="mode" :value="mode">{{p(mode)}}</option></select></label><div v-if="draft.breakMode==='duration'" class="wf-grid"><label>{{p('breakMinutes')}}<input v-model.number="draft.breakMinutes" type="number" min="1" max="1440" required></label><label>{{p('breakAfterMinutes')}}<input v-model.number="draft.breakAfterMinutes" type="number" :min="draft.breakMinutes" max="1440" required></label></div><p v-if="draft.breakMode==='duration'" class="wf-hint">{{p('durationHint')}}</p><div v-if="draft.breakMode==='window'" class="wf-grid"><label>{{p('breakStartOffset')}}<input v-model.number="draft.breakStartOffset" type="number" min="0" max="1439" required></label><label>{{p('breakEndOffset')}}<input v-model.number="draft.breakEndOffset" type="number" :min="draft.breakStartOffset+1" max="1440" required></label></div><label class="wf-check"><input v-model="draft.breakPaid" type="checkbox">{{p('breakPaid')}}</label><p class="wf-hint">{{p('rulesHint')}}</p></template><label class="wf-check"><input v-model="draft.enabled" type="checkbox">{{p('enabled')}}</label></fieldset><footer class="wf-form-actions"><RouterLink class="wf-button" :to="base+'/shifts'">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy||(!!draft.rules&&!validAttendanceRules(draft.rules,duration))">{{t(busy?'saving':'save')}}</button></footer></form></section></template>

